class GFG {

    // Function to return all prime numbers up to n
    static List<int> sieve(int n)  {

        // Boolean array to mark primes
        bool[] prime = new bool[n + 1];
        for (int i = 0; i <= n; i++) {
            prime[i] = true;
        }

        // Sieve of Eratosthenes
        for (int p = 2; p * p <= n; p++)
